import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';
import { useSearchParams } from 'react-router-dom';

import { Button, type TableColumnsType, Typography } from 'antd';
import cn from 'classnames';

import ReportsIcon from 'assets/images/icons/reports.svg?react';
import {
	TRANSACTION_STATUSES,
	useWithdrawalRequestListQuery,
	WithdrawalRequestRead,
	WithdrawalRequestStatusEnum,
} from 'entities/Transaction';
import { getUrlParamsForApi, TransactionsFilters } from 'features/Filters';
import { useAppConfigRetrieveQuery } from 'shared/api';
import { Table } from 'shared/ui';
import { formatDate, formatNumber, getDefaultSortOrder } from 'shared/utils';

import styles from './TransactionList.module.scss';

interface ITransactionListProps extends HTMLAttributes<HTMLDivElement> {}

export const TransactionList: FC<ITransactionListProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const [searchParams] = useSearchParams();
	const { data: appConfig } = useAppConfigRetrieveQuery();
	const { data, isFetching, isLoading } = useWithdrawalRequestListQuery(getUrlParamsForApi(searchParams));

	const columns: TableColumnsType<WithdrawalRequestRead> = [
		{
			title: t('Date'),
			dataIndex: 'created_at',
			key: 'created_at',
			sorter: true,
			defaultSortOrder: getDefaultSortOrder(searchParams, 'created_at'),
			render: (created_at: string) => formatDate(new Date(created_at), 'medium'),
		},
		{
			title: t('Transaction name'),
			dataIndex: 'payment_system_account_url',
			key: 'payment_system_account_url',
			render: () => <Typography.Text>{t('Withdrawal wallet')}</Typography.Text>,
		},
		{
			title: t('Finance status'),
			dataIndex: 'status',
			key: 'status',
			render: (status: WithdrawalRequestStatusEnum) => (
				<Typography.Text type={status === WithdrawalRequestStatusEnum.Failed ? 'danger' : undefined}>
					{TRANSACTION_STATUSES[status]}
				</Typography.Text>
			),
		},
		{
			title: `${t('Total amount')}, ${appConfig?.user?.balance?.currency}`,
			dataIndex: 'amount',
			key: 'amount',
			align: 'end',
			render: (amount: string) => <Typography.Text strong>- {formatNumber(amount)}</Typography.Text>,
		},
		{
			dataIndex: 'uuid',
			key: 'uuid',
			render: (_: string, record: WithdrawalRequestRead) => (
				<div className={styles.transactionList__actions}>
					<Button type={'link'} icon={<ReportsIcon />}>
						{record.status === WithdrawalRequestStatusEnum.Failed ? t('Details') : t('Reports')}
					</Button>
					{!!record.payment_system_account_url && (
						<Button type={'link'} href={record.payment_system_account_url}>
							{t('Go to wallet')}
						</Button>
					)}
				</div>
			),
		},
	];

	return (
		<div {...props} className={cn(className, styles.transactionList)}>
			<Typography.Title level={2}>{t('Withdrawal')}</Typography.Title>
			<TransactionsFilters />
			<Table
				columns={columns}
				dataCount={data?.count}
				dataSource={data?.results}
				isFirstLoading={isLoading}
				loading={isFetching}
			/>
		</div>
	);
};
