import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, Spin, Typography } from 'antd';
import cn from 'classnames';

import SuccessIcon from 'assets/images/icons/success.svg?react';
import { WithdrawalRequestRead, WithdrawalRequestStatusEnum } from 'entities/Transaction';

import styles from './Withdrawal.module.scss';

interface IWithdrawalProps extends HTMLAttributes<HTMLDivElement> {
	withdrawal?: WithdrawalRequestRead;
	currency: string;
}

export const Withdrawal: FC<IWithdrawalProps> = ({ className, withdrawal, currency, ...props }) => {
	const { t } = useTranslation();

	return (
		<div {...props} className={cn(className, styles.withdrawal)}>
			{withdrawal?.status === WithdrawalRequestStatusEnum.InProgress && <Spin />}
			{withdrawal?.status === WithdrawalRequestStatusEnum.Success && <SuccessIcon />}

			<Typography.Title level={5}>
				{withdrawal?.status === WithdrawalRequestStatusEnum.InProgress && t('Transferring funds to telerev Wallet')}
				{withdrawal?.status === WithdrawalRequestStatusEnum.Success && t('Transfer completed')}
				{withdrawal?.status === WithdrawalRequestStatusEnum.Failed && t('Transfer failed')}
			</Typography.Title>

			<Typography.Text>
				{withdrawal?.status === WithdrawalRequestStatusEnum.InProgress &&
					t(
						'Moving funds to your wallet for further withdrawal. This usually takes less than a minute, so please keep this window open. Thank you!',
					)}
				{withdrawal?.status === WithdrawalRequestStatusEnum.Success &&
					`${withdrawal.amount} ${currency} ${t('awailable for withdrawal in your telerev Wallet.')}`}
			</Typography.Text>

			{!!withdrawal?.payment_system_account_url && (
				<Button
					disabled={withdrawal?.status !== WithdrawalRequestStatusEnum.Success}
					size="large"
					href={withdrawal?.payment_system_account_url}>
					{t('Withdraw via telerev Wallet')}
				</Button>
			)}
		</div>
	);
};
